# Does the "ratio knee" of batched compression survive a benchmark that recycles its inputs (the constant-input trap)?
# Deterministic: real zlib over messages generated by formulas, no RNG, no timing.
import zlib
def msg(i):   # varied 50-60 byte tick message: actor id, hp, x, y with digits that depend on i via mixed arithmetic
    a=(i*2654435761)%100000; h=(i*40503+17)%1000; x=(i*9973+101)%4096; y=(i*7919+13)%4096
    return f"T|actor={a:05d}|hp={h:04d}|pos={x:04d},{y:04d}|st=run;".encode()
def ratio(msgs, batch):
    raw=comp=0
    for k in range(0,len(msgs)-batch+1,batch):
        blob=b"".join(msgs[k:k+batch]); raw+=len(blob); comp+=len(zlib.compress(blob,6))
    return raw/comp
N=512; sizes=[1,2,4,8,16,32,64,128]
def curve(msgs): return [ratio(msgs,b) for b in sizes]
def knee(c, gain=0.05):
    for j in range(len(c)-1):
        if c[j+1]/c[j]-1 < gain: return sizes[j]
    return None
sets={"varied":[msg(i) for i in range(N)],
      "identical":[msg(0)]*N,
      "pool4":[msg(i%4) for i in range(N)],
      "pool16":[msg(i%16) for i in range(N)],
      "pool64":[msg(i%64) for i in range(N)]}
out={}
for name,m in sets.items():
    c=curve(m); out[name]=(c,knee(c)); print(f"{name:10} ratios",[round(x,2) for x in c],"knee@",knee(c))
# claim-checks (prediction written first): identical -> no knee by batch 128 or a huge ratio; varied -> knee near 8-16; recycled pools -> apparent knee moves up with pool size and ratios overstate varied
v=out["varied"]; idn=out["identical"]
print("per-message ratio varied vs identical:", round(v[0][0],2), round(idn[0][0],2))
over=[round(out[p][0][-1]/v[0][-1],1) for p in ("identical","pool4","pool16","pool64")]
print("batch-128 ratio overstatement vs varied (identical,pool4,pool16,pool64):",over)
kn=[out[p][1] for p in ("pool4","pool16","pool64")]
print("apparent knees pool4/pool16/pool64:",kn,"varied knee:",v[1])
def jump(c):    # first batch size at which doubling buys >1.5x more ratio (the recycled pool becomes visible)
    for j in range(len(c)-1):
        if c[j+1]/c[j]>1.5 and sizes[j]>=2: return sizes[j+1]
jumps={p:jump(out[p][0]) for p in ("pool4","pool16","pool64")}
print("batch size where the pool shows up as a ratio jump:",jumps,"(expected first batch above the pool size: 8, 32, 128)")
pred_varied_knee_8_to_16 = v[1] is not None and v[1]<=16     # my prediction before the first run; missed (knee was 64 on this fixture)
print("prediction varied knee<=16:",pred_varied_knee_8_to_16)
ok = idn[1] is None and all(x>1.5 for x in over) and jumps=={"pool4":8,"pool16":32,"pool64":128}
print("RESULT:","PASS" if ok else "FAIL",f"recycled inputs overstate batch-128 ratio {over} vs varied {v[0][-1]:.2f}; identical shows no knee; pool P appears as a ratio jump at batch {jumps}; varied knee was {v[1]} (predicted <=16, missed)")
